/**
 * Partner proof kits (integrations/): the expected Breakra result for each shared fixture, generated by the real
 * engine. The analysis_id is deterministic and the same whether a contract is sent as YAML text, JSON text or an
 * object, so a partner's agent can be checked against these files. tests/integrations.test.ts keeps them in sync.
 *
 *   bun scripts/integration-kits.ts      # after an engine or fixture change
 */
import { readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { analyze } from "../src/analyze";
import { parseSpecText } from "../src/core/validate";

const root = fileURLToPath(new URL("..", import.meta.url));
export const CASES = ["breaking", "safe"] as const;
export type Case = (typeof CASES)[number];

export const fixture = (name: Case, side: "before" | "after") =>
  readFileSync(join(root, "integrations/fixtures", name, `${side}.yaml`), "utf8");

export async function expected(name: Case): Promise<string> {
  const result = await analyze({
    before: parseSpecText(fixture(name, "before"), "before"),
    after: parseSpecText(fixture(name, "after"), "after"),
  });
  // metadata.duration_ms is the only non-deterministic field: leave it out so the files can be compared.
  const { duration_ms: _ignored, ...metadata } = result.metadata;
  return `${JSON.stringify({ ...result, metadata }, null, 2)}\n`;
}

if (import.meta.main) {
  for (const name of CASES) {
    writeFileSync(join(root, "integrations/fixtures", name, "expected.json"), await expected(name));
  }
  console.log(`expected results written: ${CASES.join(", ")}`);
}
